window.kbPageData["views/entry/k-1e75d0e7dee24a7f"] = {"key":"entry/k-1e75d0e7dee24a7f","state":{"route":"entry/k-1e75d0e7dee24a7f"},"node":{"id":"k-1e75d0e7dee24a7f","mode":"k","title":"美丽中国先行区建设","type":"概念与词义","domain":"生态环境","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["ecology"],"主类":["概念与词义"],"出处性质":["机构注释"],"学科":["生态环境"],"来源主题":["生态环境与能源"],"资料类别":["非时政"]},"directorySummary":"美丽中国先行区建设\n建设美丽中国先行区是全面推进美丽中国建设的重要抓手，是构建美丽中国建设新格\n局的关键支撑。要以习近平新时代中国特色社会主义思想为指导，深入贯彻党的二十大和二\n十届二中、三中全会精神，全面贯彻习近平生态文明思想，牢固树立和践行绿水青山就是金\n山银山的理念，落实全国生态环境保护大会要…","sources":[{"id":"798fc8a6855938e2","label":"美丽中国先行区建设","topic":"生态环境与能源","category":"非时政","text":"美丽中国先行区建设\n建设美丽中国先行区是全面推进美丽中国建设的重要抓手，是构建美丽中国建设新格\n局的关键支撑。要以习近平新时代中国特色社会主义思想为指导，深入贯彻党的二十大和二\n十届二中、三中全会精神，全面贯彻习近平生态文明思想，牢固树立和践行绿水青山就是金\n山银山的理念，落实全国生态环境保护大会要求，聚焦全面推进美丽中国建设中心任务，以\n深化污染防治攻坚、改善生态环境质量、增进民生福祉为着力点，坚持改革创新、重点突\n破、示范带动，在区域、省域、城市、县域各层级，聚焦推动绿色低碳发展、促进生态环境\n根本好转、加强生态保护修复、筑牢生态安全底线、深化生态文明体制改革等目标任务，分\n级分类建设美丽中国先行区（以下简称先行区），到 2027 年底前形成一批实践创新和制度\n创新成果，久久为功建成若干各美其美、群众满意的示范样板，为全面推进美丽中国建设积\n累经验、树立标杆。\n——《关于建设美丽中国先行区的实施意见》","source":{"doc":"6cbfb01fe723bba64b75","first":12,"last":12,"page":12,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"ecology","title":"生态保护与绿色转型"}],"units":{"k-1e75d0e7dee24a7f":[]}};
